class Solution {
public:
    vector<string> findAndReplacePattern(vector<string>& words, string pattern) {
        vector<string> result;
        for (const string& word : words) {
            if (isIsomorphic(word, pattern)) {
                result.push_back(word);
            }
        }
        return result;
    }

private:
    bool isIsomorphic(const string& word, const string& pattern) {
        int fwd[26], rev[26];
        for (int i = 0; i < 26; i++) {
            fwd[i] = -1;
            rev[i] = -1;
        }
        int n = (int)word.size();
        for (int i = 0; i < n; i++) {
            int w = word[i] - 'a';
            int p = pattern[i] - 'a';
            if (fwd[w] == -1) fwd[w] = p;
            if (rev[p] == -1) rev[p] = w;
            if (fwd[w] != p || rev[p] != w) {
                return false;
            }
        }
        return true;
    }
};
